"""Source-pinned terrain products, generated by the delivered D8/control split."""
from __future__ import annotations

import copy
import csv
import io
import shutil
import zipfile
from pathlib import Path

from common import MODEL, read_json, write_json, now
from contracts import freeze_input_selection
from diagnostic_jobs import make_point_engine, sha

CONTEXT = {'projectId': 'nananxi-xufan', 'resolutionId': '1km',
           'modelConfigId': 'nananxi-xufan-1km',
           'contextKey': 'nananxi-xufan:distributed-xinanjiang:nananxi-xufan-1km'}
SOURCE_FILES = {
    'dem.asc': 'data_interface/spatial/nan_an_dem_utm50_30m_clipped.asc',
    'control.json': 'data_interface/spatial/xufan_70115800_control_point_snapped_v1.json',
    'basin.geojson': 'data_interface/spatial/南安溪流域边界.geojson',
}
RASTERS = ('dem', 'routing-units', 'flow-direction', 'accumulation-area', 'stream-mask')
FILES = frozenset({f'{name}.{extension}' for name in RASTERS for extension in ('asc', 'prj')} | {
    'terrain-network.png', 'routing-units.png', 'reaches.geojson', 'control.geojson',
    'basin.geojson', 'grid.geojson', 'topology.json', 'grid-to-unit.csv', 'units.csv', 'README.txt'})
PREVIEWS = {'terrain-network.png', 'routing-units.png'}


def source_evidence(bundle):
    paths = {**{name: MODEL / path for name, path in SOURCE_FILES.items()},
             **{name: bundle['paths'][key] for name, key in (
                 ('topology.json', 'topology'), ('grid.geojson', 'geometry'), ('grid-to-unit.csv', 'mapping'))},
             'adapter.py': Path(__file__), 'diagnostic_jobs.py': Path(__file__).with_name('diagnostic_jobs.py')}
    for name in ('spatial', 'control_split', 'point_query', 'raster_formats'):
        paths[f'{name}.py'] = MODEL / f'code/xaj_routing/{name}.py'
    return {name: sha(path) for name, path in paths.items()}


def normalize_spatial(request, products):
    allowed = {'runType', 'requestId', 'context', 'inputs', 'lineage', 'spatialEvidence'}
    if not isinstance(request, dict) or request.get('runType') != 'spatialExport' or set(request) - allowed:
        raise ValueError('空间成果请求包含未知字段')
    request = copy.deepcopy(request)
    if request.get('context', CONTEXT) != CONTEXT:
        raise ValueError('空间成果对应南安溪 1 km 模型')
    if not isinstance(request.get('inputs', {}), dict) or set(request.get('inputs', {})) - {'bundleVersionId', 'bundleManifestSHA256'}:
        raise ValueError('空间成果只能选择登记输入版本')
    request, bundle = freeze_input_selection(request, products)
    evidence = source_evidence(bundle)
    if request.get('spatialEvidence', evidence) != evidence:
        raise ValueError('空间来源已改变，请重新生成成果')
    request.update(context=copy.deepcopy(CONTEXT), spatialEvidence=evidence)
    return request


def unit_raster(engine, topology):
    """Check the entire registered reach/unit identity before assigning codes."""
    import numpy as np
    frozen = {row['reach_id']: row for row in topology['reaches']}
    if set(frozen) != set(engine.reach_by_id):
        raise ValueError('提取河网与登记拓扑不同')
    for reach in engine.topology_result.reaches:
        expected = frozen[reach.reach_id]
        for key, value in [('start_cell', list(reach.start_cell)), ('end_cell', list(reach.end_cell)),
                           ('downstream_reach_id', reach.downstream_reach_id), ('cell_count', len(reach.cells))]:
            if expected[key] != value:
                raise ValueError(f'河段 {reach.reach_id} 的 {key} 与登记拓扑不同')
        if not np.isclose(expected['length_km'], reach.length_km, rtol=0, atol=1e-9):
            raise ValueError('河长与登记拓扑不同')
    units = sorted(topology['units'], key=lambda row: row['unit_id'])
    native = {row['unit_id']: row for row in engine.topology_result.units}
    if set(native) != {row['unit_id'] for row in units} or len({row['reach_id'] for row in units}) != len(units):
        raise ValueError('汇流单元身份不一致')
    codes = {row['reach_id']: index + 1 for index, row in enumerate(units)}
    labels = np.full(engine.mask.shape, -9999, dtype=np.int32)
    labels[engine.mask] = 0  # Valid terrain draining outside the extracted network.
    for cell, reach in engine.assignments.items():
        if reach is not None:
            if reach not in codes or not engine.mask[cell]:
                raise ValueError('汇流栅格归属无效')
            labels[cell] = codes[reach]
    rows = []
    for index, unit in enumerate(units, 1):
        count = int(np.count_nonzero(labels == index))
        original = native[unit['unit_id']]
        if (unit['reach_id'] != original['reach_id'] or unit['cell_count'] != count
                or not np.isclose(unit['area_km2'], count * engine.grid.cellsize ** 2 / 1e6, rtol=0, atol=1e-9)):
            raise ValueError('汇流单元面积与登记拓扑不同')
        rows.append({'code': index, 'unit_id': unit['unit_id'], 'reach_id': unit['reach_id'],
                     'cell_count': count, 'area_km2': unit['area_km2']})
    return labels, rows


def write_raster(path, values, grid):
    import numpy as np
    with Path(path).open('w', encoding='ascii', newline='\n') as stream:
        for key, value in [('ncols', grid.ncols), ('nrows', grid.nrows), ('xllcorner', grid.xllcorner),
                           ('yllcorner', grid.yllcorner), ('cellsize', grid.cellsize), ('NODATA_value', -9999)]:
            stream.write(f'{key} {value}\n')
        np.savetxt(stream, values, fmt='%.17g')


def render_maps(folder, engine, labels, rows):
    import numpy as np
    from matplotlib.figure import Figure
    from matplotlib.backends.backend_agg import FigureCanvasAgg
    from matplotlib import colormaps, font_manager, rc_context
    from matplotlib.colors import ListedColormap, BoundaryNorm, LinearSegmentedColormap
    from matplotlib.patches import Patch
    from xaj_routing.raster_formats import cell_center_xy

    fonts = {font.name for font in font_manager.fontManager.ttflist}
    selected = next((name for name in ('Microsoft YaHei', 'SimHei', 'Noto Sans CJK SC', 'SimSun') if name in fonts), 'DejaVu Sans')
    grid = engine.grid
    extent = [grid.xllcorner / 1000, (grid.xllcorner + grid.ncols * grid.cellsize) / 1000,
              grid.yllcorner / 1000, (grid.yllcorner + grid.nrows * grid.cellsize) / 1000]
    colors = ['#ece8dc'] + [colormaps['tab20'](i) for i in range(20)] + [colormaps['tab20b'](i) for i in range(12)]
    palette = ListedColormap(colors)
    terrain_palette = LinearSegmentedColormap.from_list('nanan_terrain', ['#e3ebcc', '#abc497', '#799779', '#c4b591', '#8b7865', '#f2efe6'])
    with rc_context({'font.family': selected, 'axes.unicode_minus': False, 'font.size': 9}):
        for mode, filename, title in [('terrain', 'terrain-network.png', '南安溪 · 地形与河网'),
                                      ('units', 'routing-units.png', '南安溪 · 汇流单元分区')]:
            figure = Figure(figsize=(11.8, 9.6), dpi=160, facecolor='white')
            FigureCanvasAgg(figure)
            ax = figure.add_axes([.09, .12, .56, .76])
            ax.set_facecolor('#f3f6f3')
            values = np.ma.masked_where(~engine.mask, grid.elevation if mode == 'terrain' else labels)
            if mode == 'terrain':
                layer = ax.imshow(values, origin='upper', extent=extent, cmap=terrain_palette, interpolation='nearest')
                cax = figure.add_axes([.72, .48, .025, .32])
                figure.colorbar(layer, cax=cax, label='高程（m）')
            else:
                ax.imshow(values, origin='upper', extent=extent, cmap=palette,
                          norm=BoundaryNorm(np.arange(-.5, len(colors) + .5), len(colors)), interpolation='nearest')
                legend = [Patch(facecolor=colors[row['code']], label=row['reach_id']) for row in rows]
                legend.append(Patch(facecolor=colors[0], label='未归属栅格'))
                figure.legend(handles=legend, loc='upper left', bbox_to_anchor=(.69, .86), ncol=2,
                              frameon=False, fontsize=8, title='汇流单元 · 对应河段', labelspacing=.85)
            for reach in engine.topology_result.reaches:
                xy = np.asarray([cell_center_xy(grid, *cell) for cell in reach.cells]) / 1000
                ax.plot(xy[:, 0], xy[:, 1], color='#0c6083', linewidth=.9, zorder=3)
            cell = engine.control_points[0]['snapped']['cell']
            x, y = np.asarray(cell_center_xy(grid, *cell)) / 1000
            ax.scatter([x], [y], s=45, color='#b94e32', edgecolors='white', zorder=4)
            ax.annotate('徐畈', (x, y), xytext=(8, 3), textcoords='offset points', color='#9c3d26')
            ax.annotate('N', xy=(.94, .96), xytext=(.94, .85), xycoords='axes fraction', ha='center',
                        arrowprops={'arrowstyle': '-|>', 'color': '#283f36'}, color='#283f36')
            x0, y0 = extent[0] + .6, extent[2] + .6
            ax.plot([x0, x0 + 2], [y0, y0], color='#283f36', linewidth=3)
            ax.text(x0 + 1, y0 + .2, '2 km', ha='center')
            ax.ticklabel_format(useOffset=False, style='plain')
            ax.set_xlabel('东向坐标（km）')
            ax.set_ylabel('北向坐标（km）')
            ax.set_xlim(extent[:2]); ax.set_ylim(extent[2:])
            ax.set_aspect('equal')
            figure.text(.09, .935, title, fontsize=20, weight='bold', color='#294e3a')
            figure.text(.09, .90, '30 m 地形  /  D8 河网  /  徐畈控制断面切分', color='#65756c', fontsize=10)
            figure.text(.70, .21, f'{len(rows)} 个汇流单元\n{int(engine.mask.sum()):,} 个有效栅格\n'
                        f'{int(np.count_nonzero(labels > 0)):,} 个归属栅格\n河网起始面积 1 km²', linespacing=1.8, color='#405d4e')
            figure.text(.09, .045, 'WGS 84 / UTM 50N · EPSG:32650    |    数值与图件采用同一登记拓扑', color='#65756c', fontsize=9)
            figure.savefig(folder / filename, dpi=160)
            figure.clear()


def generate(folder, request, products):
    import numpy as np
    from pyproj import CRS
    from xaj_routing.raster_formats import cell_center_xy

    frozen = normalize_spatial(request, products)
    bundle = products.resolve(frozen['inputs']['bundleVersionId'])
    output = folder / 'spatial'
    output.mkdir(exist_ok=True)
    write_json(folder / 'progress.json', {'progress': 10, 'stageLabel': '提取 30 m 河网与汇流分区'})
    engine = make_point_engine(bundle, output, {})
    topology = read_json(bundle['paths']['topology'])
    labels, rows = unit_raster(engine, topology)
    write_json(folder / 'progress.json', {'progress': 50, 'stageLabel': '保存地形、河网及汇流单元'})
    shutil.copyfile(MODEL / SOURCE_FILES['dem.asc'], output / 'dem.asc')
    for name, values in [('routing-units', labels), ('flow-direction', engine.topology_result.flow_dir),
                         ('accumulation-area', engine.topology_result.accumulation_area_km2),
                         ('stream-mask', engine.topology_result.stream_raster.astype(int))]:
        write_raster(output / f'{name}.asc', np.where(engine.mask, values, -9999), engine.grid)
    for name in RASTERS:
        (output / f'{name}.prj').write_text(CRS.from_epsg(32650).to_wkt(version='WKT1_ESRI'), encoding='utf-8')
    features = []
    for reach in engine.topology_result.reaches:
        coordinates = [list(engine.inverse_transformer.transform(*cell_center_xy(engine.grid, *cell))) for cell in reach.cells]
        geometry = {'type': 'LineString', 'coordinates': coordinates} if len(coordinates) > 1 else {'type': 'Point', 'coordinates': coordinates[0]}
        features.append({'type': 'Feature', 'properties': {**next(row for row in rows if row['reach_id'] == reach.reach_id),
                         'path_cell_count': len(reach.cells), 'downstream_reach_id': reach.downstream_reach_id,
                         'length_km': reach.length_km}, 'geometry': geometry})
    write_json(output / 'reaches.geojson', {'type': 'FeatureCollection', 'features': features})
    control = engine.control_points[0]
    coordinate = list(engine.inverse_transformer.transform(*cell_center_xy(engine.grid, *control['snapped']['cell'])))
    write_json(output / 'control.geojson', {'type': 'FeatureCollection', 'features': [{'type': 'Feature',
               'properties': {'name': '徐畈', 'reach_id': 'R0020_UP', 'cell': control['snapped']['cell']},
               'geometry': {'type': 'Point', 'coordinates': coordinate}}]})
    for filename, source in [('basin.geojson', MODEL / SOURCE_FILES['basin.geojson']),
                             ('grid.geojson', bundle['paths']['geometry']), ('topology.json', bundle['paths']['topology']),
                             ('grid-to-unit.csv', bundle['paths']['mapping'])]:
        shutil.copyfile(source, output / filename)
    with (output / 'units.csv').open('w', encoding='utf-8-sig', newline='') as stream:
        writer = csv.DictWriter(stream, fieldnames=list(rows[0]))
        writer.writeheader(); writer.writerows(rows)
    (output / 'README.txt').write_text(
        '南安溪空间成果\n\n栅格：ESRI ASCII + 同名 PRJ，EPSG:32650，30 m，首行为北侧，NoData=-9999。\n'
        'dem.asc 为原始高程逐字节副本；PNG 高程也采用原始 DEM。D8 计算沿用原模型填洼流程。\n'
        'routing-units.asc：1–32 对应 units.csv，0 为有效但未归属提取河网的栅格。\n'
        'flow-direction.asc：东1、东南2、南4、西南8、西16、西北32、北64、东北128；0 为无下游。\n'
        'accumulation-area.asc：上游汇水面积，km²；stream-mask.asc：河网1，其余有效栅格0。\n'
        'reaches.geojson / control.geojson：WGS84 经纬度，河道按真实栅格中心连接，不作平滑。\n'
        'basin.geojson / grid.geojson：原登记经纬度矢量副本，不重投影；源文件未单列 crs。\n'
        'grid-to-unit.csv 为模型面积权重，不以栅格个数重新替代。\n'
        'PNG 为带图例的排版图，不是地理配准栅格；GIS 分析请使用 ASC/PRJ 和 GeoJSON。\n'
        'manifest.json 记录版本、来源及所有成果文件的 SHA256。\n', encoding='utf-8')
    write_json(folder / 'progress.json', {'progress': 75, 'stageLabel': '绘制地形河网图与汇流分区图'})
    render_maps(output, engine, labels, rows)
    # Detect edits while the numerical extraction/rendering was in flight.
    if source_evidence(bundle) != frozen['spatialEvidence']:
        raise ValueError('生成期间空间来源改变，请重新生成')
    summary = {'cellSizeM': engine.grid.cellsize, 'ncols': engine.grid.ncols, 'nrows': engine.grid.nrows,
               'validCells': int(engine.mask.sum()), 'assignedCells': int(np.count_nonzero(labels > 0)),
               'unassignedCells': int(np.count_nonzero(labels == 0)), 'unitCount': len(rows),
               'reachCount': len(features), 'gridCount': len(read_json(bundle['paths']['geometry'])['features']),
               'areaKm2': float(engine.mask.sum() * engine.grid.cellsize ** 2 / 1e6),
               'assignedAreaKm2': float(np.count_nonzero(labels > 0) * engine.grid.cellsize ** 2 / 1e6),
               'elevationMinM': float(engine.grid.elevation[engine.mask].min()),
               'elevationMaxM': float(engine.grid.elevation[engine.mask].max()), 'crs': 'EPSG:32650',
               'streamThresholdKm2': 1.0, 'nodata': -9999, 'unassignedCode': 0,
               'extent': [engine.grid.xllcorner, engine.grid.yllcorner,
                          engine.grid.xllcorner + engine.grid.ncols * engine.grid.cellsize,
                          engine.grid.yllcorner + engine.grid.nrows * engine.grid.cellsize]}
    manifest = {'schemaVersion': '1.0', 'taskId': folder.name, 'createdAt': now(),
                'inputs': frozen['inputs'], 'sourceEvidence': frozen['spatialEvidence'], 'summary': summary,
                'coordinateReferences': {'rasters': 'EPSG:32650', 'generatedVectors': 'EPSG:4326',
                                         'registeredVectors': {name: read_json(output / name).get('crs') for name in ('basin.geojson', 'grid.geojson')}},
                'files': [{'name': name, 'size': (output / name).stat().st_size, 'sha256': sha(output / name)} for name in sorted(FILES)]}
    write_json(output / 'manifest.json', manifest)
    result = {'schemaVersion': '2.0', 'taskId': folder.name, 'runType': 'spatialExport',
              'resultVersionId': f'SPATIAL-{folder.name}', 'context': frozen['context'], 'lineage': frozen['lineage'],
              'spatial': {'summary': summary, 'manifestSHA256': sha(output / 'manifest.json'),
                          'previews': sorted(PREVIEWS), 'files': manifest['files']}}
    write_json(folder / 'result.json', result)
    return result


def artifact_bytes(folder, result, filename=None):
    """Only successful, hash-matched, fixed-name artifacts can leave the task."""
    if result.get('runType') != 'spatialExport' or 'spatial' not in result:
        raise ValueError('该任务没有空间成果')
    root = (folder / 'spatial').resolve()
    if folder.is_symlink() or root != folder.resolve() / 'spatial' or (folder / 'spatial').is_symlink():
        raise ValueError('空间成果目录越界')

    def read(name, expected):
        path = root / name
        if path.is_symlink() or path.resolve().parent != root or not path.is_file():
            raise ValueError('空间成果文件无效')
        if path.stat().st_size > 64 * 1024 * 1024:
            raise ValueError('空间成果文件超过 64 MB')
        data = path.read_bytes()
        import hashlib
        if hashlib.sha256(data).hexdigest() != expected:
            raise ValueError('空间成果校验不一致，请重新生成')
        return data

    import json
    manifest_bytes = read('manifest.json', result['spatial']['manifestSHA256'])
    manifest = json.loads(manifest_bytes)
    entries = {row['name']: row for row in manifest['files']}
    if set(entries) != FILES or len(entries) != len(manifest['files']) or manifest['taskId'] != folder.name:
        raise ValueError('空间成果目录不一致')
    if filename is not None:
        if filename not in PREVIEWS:
            raise ValueError('空间图件名称无效')
        return read(filename, entries[filename]['sha256'])
    if sum(row['size'] for row in entries.values()) > 64 * 1024 * 1024:
        raise ValueError('空间成果包超过 64 MB')
    stream = io.BytesIO()
    with zipfile.ZipFile(stream, 'w', zipfile.ZIP_DEFLATED) as archive:
        archive.writestr('manifest.json', manifest_bytes)
        total = len(manifest_bytes)
        for name, entry in entries.items():
            data = read(name, entry['sha256'])
            total += len(data)
            if total > 64 * 1024 * 1024:
                raise ValueError('空间成果包超过 64 MB')
            if len(data) != entry['size']:
                raise ValueError('空间成果文件长度不一致')
            archive.writestr(name, data)
    return stream.getvalue()
